func (snapshotter *Snapshotter) SnapshotOnce(ctx context.Context) ([]string, error) {
	snapshotter.passMu.Lock()
	defer snapshotter.passMu.Unlock()
	ctx, cancel := context.WithTimeout(ctx, snapshotPassTimeout)
	defer cancel()
	if snapshotter.uploaded == nil {
		snapshotter.uploaded = map[string]upload{}
	}
	var written []string
	var failures []error
	start := snapshotter.nextBucket
	for index := range len(snapshotter.Buckets) {
		bucket := snapshotter.Buckets[(start+index)%len(snapshotter.Buckets)]
		wrote, state, err := snapshotter.snapshot(ctx, bucket)
		snapshotter.recordCheck(bucket, wrote, state, err)
		if err != nil {
			failures = append(failures, err)
		} else if wrote {
			written = append(written, bucket)
		}
	}
	if len(snapshotter.Buckets) > 0 {
		snapshotter.nextBucket = (start + 1) % len(snapshotter.Buckets)
	}
	checkedAt := snapshotter.now()
	snapshotter.statusMu.Lock()
	snapshotter.lastCheckAt = checkedAt
	snapshotter.statusMu.Unlock()
	return written, errors.Join(failures...)
}

func (snapshotter *Snapshotter) snapshot(ctx context.Context, bucket string) (wrote bool, state string, err error) {
	// Stream asks the stream leader for its current info on every call;
	// CachedInfo returns that reply.
	stream, err := snapshotter.JS.Stream(ctx, "KV_"+bucket)
	if errors.Is(err, jetstream.ErrStreamNotFound) {
		return false, "absent", nil
	}
	if err != nil {
		return false, "", fmt.Errorf("inspect %s: %w", bucket, err)
	}
	info := stream.CachedInfo()
	created, sequence := info.Created, info.State.LastSeq
	last, known := snapshotter.uploaded[bucket]
	if sequence == 0 {
		return false, "empty", nil
	}
	// An unchanged ETag proves the object still holds this stream at a lower
	// sequence, so the write needs no read.
	if known && last.created.Equal(created) && sequence > last.sequence {
		if err := snapshotter.writeSnapshot(ctx, info, bucket, last.etag); err == nil {
			return true, "current", nil
		}
		// The object moved, vanished or could not be written: forget it
		// and decide from a fresh read.
		delete(snapshotter.uploaded, bucket)
	}
	stored, etag, found, err := snapshotter.Objects.Get(ctx, bucket)
	if err != nil {
		return false, "", err
	}
	if found {
		if stored.StreamCreated.After(created) {
			return false, "", fmt.Errorf("%w: %s was snapshotted from a stream created at %s, after this one (%s)",
				ErrNewerLineage, bucket, stored.StreamCreated.Format(time.RFC3339Nano), created.Format(time.RFC3339Nano))
		}
		if stored.StreamCreated.Equal(created) && stored.Sequence >= sequence {
			snapshotter.uploaded[bucket] = upload{created: created, sequence: stored.Sequence, etag: etag}
			return false, "current", nil
		}
	}
	if err := snapshotter.writeSnapshot(ctx, info, bucket, etag); err != nil {
		return false, "", err
	}
	return true, "current", nil
}

func (snapshotter *Snapshotter) writeSnapshot(ctx context.Context, info *jetstream.StreamInfo, bucket, etag string) error {
	document, err := capture(ctx, snapshotter.JS, info, snapshotter.Objects.Cell, bucket, snapshotter.now())
	if err != nil {
		return err
	}
	etag, err = snapshotter.Objects.Put(ctx, document, etag)
	if err != nil {
		return err
	}
	snapshotter.uploaded[bucket] = upload{created: info.Created, sequence: info.State.LastSeq, etag: etag}
	return nil
}

// capture reads the latest value of every key. Sequence is the stream's last
// sequence before the read, so the snapshot holds at least that state; a
// change during the read moves the sequence and is captured next pass.
func capture(ctx context.Context, js jetstream.JetStream, info *jetstream.StreamInfo, cell, bucket string,
	now time.Time,
) (Document, error) {
	ctx, cancel := context.WithTimeout(ctx, captureTimeout)
	defer cancel()
	kv, err := js.KeyValue(ctx, bucket)
	if err != nil {
		return Document{}, fmt.Errorf("open %s: %w", bucket, err)
	}
	watcher, err := kv.WatchAll(ctx, jetstream.IgnoreDeletes())
	if err != nil {
		return Document{}, fmt.Errorf("read %s: %w", bucket, err)
	}
	defer func() {
		_ = watcher.Stop()
		// The watcher closes Updates only once a delivery blocked on its full
		// channel returns, so drain until it closes, for at most a minute.
		go func() {
			timeout := time.NewTimer(drainTimeout)
			defer timeout.Stop()
			for {
				select {
				case _, ok := <-watcher.Updates():
					if !ok {
						return
					}
				case <-timeout.C:
					return
				}
			}
		}()
	}()
	values := map[string][]byte{}
	size := 0
	for {
		var entry jetstream.KeyValueEntry
		var ok bool
		select {
		case entry, ok = <-watcher.Updates():
		case <-ctx.Done():
			return Document{}, fmt.Errorf("read %s: %w", bucket, ctx.Err())
		}
		if !ok {
			return Document{}, fmt.Errorf("read %s: watcher closed before its initial values", bucket)
		}
		if entry == nil {
			break
		}
		values[entry.Key()] = entry.Value()
		if size += len(entry.Key()) + len(entry.Value()); size > maxDocumentBytes {
			return Document{}, fmt.Errorf("kv snapshot of %s exceeds %d bytes", bucket, maxDocumentBytes)
		}
	}
	entries := make([]Entry, 0, len(values))
	for key, value := range values {
		entries = append(entries, Entry{Key: key, Value: value})
	}
	slices.SortFunc(entries, func(a, b Entry) int { return strings.Compare(a.Key, b.Key) })
	config := info.Config
	return Document{Version: documentVersion, Cell: cell, Bucket: bucket, StreamCreated: info.Created.UTC(),
		Sequence: info.State.LastSeq, TakenAt: now, Entries: entries,
		Config: BucketConfig{Description: config.Description, History: uint8(config.MaxMsgsPerSubject),
			MaxValueSize: config.MaxMsgSize, Compression: config.Compression != jetstream.NoCompression}}, nil
}

status.text:
func (snapshotter *Snapshotter) Status() observability.KVSnapshotView {
	interval := snapshotInterval
	view := observability.KVSnapshotView{State: "current", CheckTimeoutSeconds: snapshotPassTimeout.Seconds(),
		Buckets: make([]observability.KVSnapshotBucketView, 0, len(snapshotter.Buckets))}
	if len(snapshotter.Buckets) == 0 {
		view.State = "unknown"
	}
	snapshotter.statusMu.RLock()
	view.LastCheckAt = snapshotter.lastCheckAt
	for _, bucket := range snapshotter.Buckets {
		status, ok := snapshotter.status[bucket]
		if !ok {
			status = observability.KVSnapshotBucketView{Bucket: bucket, State: "unknown"}
		}
		view.Buckets = append(view.Buckets, status)
		switch status.State {
		case "current", "absent", "empty":
		case "failed":
			view.State = "failed"
		default:
			if view.State != "failed" {
				view.State = "unknown"
			}
		}
	}
	snapshotter.statusMu.RUnlock()
	if view.LastCheckAt.IsZero() && view.State != "failed" {
		view.State = "unknown"
	}
	view.IntervalSeconds = interval.Seconds()
	if snapshotter.Leader != nil && !snapshotter.Leader() {
		view.State = "follower"
	} else if !view.LastCheckAt.IsZero() {
		view.Overdue = snapshotter.now().After(view.LastCheckAt.Add(interval + snapshotPassTimeout))
		if view.Overdue && view.State != "failed" {
			view.State = "unknown"
		}
	}
	return view
}

func (snapshotter *Snapshotter) recordCheck(bucket string, wrote bool, state string, err error) {
	now := snapshotter.now()
	snapshotter.statusMu.Lock()
	defer snapshotter.statusMu.Unlock()
	if snapshotter.status == nil {
		snapshotter.status = map[string]observability.KVSnapshotBucketView{}
	}
	status := snapshotter.status[bucket]
	status.Bucket, status.LastCheckAt = bucket, now
	status.State, status.ErrorClass = state, ""
	if err != nil {
		status.State, status.ErrorClass = "failed", snapshotErrorClass(err)
	} else if state == "current" {
		status.State, status.LastCurrentAt = "current", now
		status.Sequence = snapshotter.uploaded[bucket].sequence
		if wrote {
			status.LastUploadedAt = now
		}
	}
	snapshotter.status[bucket] = status
}

func (snapshotter *Snapshotter) now() time.Time {
	if snapshotter.Now != nil {
		return snapshotter.Now().UTC()
	}
	return time.Now().UTC()
}

func snapshotErrorClass(err error) string {
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, context.Canceled):
		return "canceled"
	case errors.Is(err, ErrNewerLineage):
		return "newer_lineage"
	case errors.Is(err, ErrConflict):
		return "conflict"
	}
	if serviceErr, ok := errors.AsType[serviceError](err); ok {
		switch serviceErr.GetHTTPStatusCode() {
		case http.StatusUnauthorized, http.StatusForbidden:
			return "unauthorized"
		case http.StatusTooManyRequests:
			return "throttled"
		}
	}
	return "unavailable"
}

objects.text:
func discoverObjects(ctx context.Context, client objectstorage.ObjectStorageClient, region, cell string) (*Objects, error) {
	entry, ok := catalog.CellForOCIRegion(region)
	if !ok || cell != entry.Name() {
		return nil, errors.New("kv snapshot region does not match the controller cell")
	}
	name, err := naming.RegionCell(entry.Cell).Name()
	if err != nil {
		return nil, err
	}
	bucket := name + "-head"
	namespace, err := client.GetNamespace(ctx, objectstorage.GetNamespaceRequest{})
	if err != nil {
		return nil, fmt.Errorf("discover kv snapshot namespace: %w", err)
	}
	if namespace.Value == nil || !namespacePattern.MatchString(*namespace.Value) {
		return nil, errors.New("kv snapshot namespace is missing or invalid")
	}
	response, err := client.GetBucket(ctx, objectstorage.GetBucketRequest{
		NamespaceName: namespace.Value, BucketName: new(bucket),
	})
	if err != nil {
		return nil, fmt.Errorf("inspect regional kv snapshot bucket: %w", err)
	}
	if response.Namespace == nil || *response.Namespace != *namespace.Value ||
		response.Name == nil || *response.Name != bucket ||
		response.Versioning != objectstorage.BucketVersioningEnabled ||
		response.KmsKeyId == nil || !strings.HasPrefix(*response.KmsKeyId, "ocid1.key.") {
		return nil, errors.New("regional kv snapshot bucket must match its identity and retain versions with its managed KMS key")
	}
	return &Objects{Client: client, Namespace: *namespace.Value, Bucket: bucket, Cell: cell}, nil
}

// Get returns the bucket's snapshot and its ETag. Only OCI's ObjectNotFound
// reports an absent snapshot; a missing bucket or a refused grant, which OCI
// also answers with 404, is an error, so a restore never mistakes an
// unreadable snapshot for an empty one.
func (objects *Objects) Get(ctx context.Context, bucket string) (Document, string, bool, error) {
	response, err := objects.Client.GetObject(ctx, objectstorage.GetObjectRequest{
		NamespaceName: new(objects.Namespace), BucketName: new(objects.Bucket),
		ObjectName: new(objectName(objects.Cell, bucket)),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[serviceError](err); ok &&
			serviceErr.GetHTTPStatusCode() == http.StatusNotFound && serviceErr.GetCode() == "ObjectNotFound" {
			return Document{}, "", false, nil
		}
		return Document{}, "", false, fmt.Errorf("read kv snapshot of %s: %w", bucket, err)
	}
	if response.Content == nil {
		return Document{}, "", false, fmt.Errorf("kv snapshot of %s has no body", bucket)
	}
	data, err := io.ReadAll(io.LimitReader(response.Content, maxDocumentBytes+1))
	if err = errors.Join(err, response.Content.Close()); err != nil {
		return Document{}, "", false, fmt.Errorf("read kv snapshot of %s: %w", bucket, err)
	}
	if response.ETag == nil || *response.ETag == "" ||
		response.ContentLength == nil || *response.ContentLength != int64(len(data)) {
		return Document{}, "", false, fmt.Errorf("kv snapshot of %s lacks its ETag or was truncated", bucket)
	}
	document, err := decodeDocument(data, objects.Cell, bucket)
	if err != nil {
		return Document{}, "", false, err
	}
	return document, *response.ETag, true, nil
}

// Put writes document only while the object still has etag, or only while
// it is absent when etag is empty, and returns the new ETag. OCI checks the
// body against its SHA-256.
func (objects *Objects) Put(ctx context.Context, document Document, etag string) (string, error) {
	data, err := encodeDocument(document)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(data)
	request := objectstorage.PutObjectRequest{
		NamespaceName: new(objects.Namespace), BucketName: new(objects.Bucket),
		ObjectName:    new(objectName(objects.Cell, document.Bucket)),
		PutObjectBody: io.NopCloser(bytes.NewReader(data)), ContentLength: new(int64(len(data))),
		ContentType:          new("application/json"),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256,
		OpcContentSha256:     new(base64.StdEncoding.EncodeToString(digest[:])),
	}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = new(etag)
	}
	response, err := objects.Client.PutObject(ctx, request)
	if err != nil {
		if serviceErr, ok := errors.AsType[serviceError](err); ok &&
			serviceErr.GetHTTPStatusCode() == http.StatusPreconditionFailed {
			return "", ErrConflict
		}
		return "", fmt.Errorf("write kv snapshot of %s: %w", document.Bucket, err)
	}
	if response.ETag == nil || *response.ETag == "" {
		return "", fmt.Errorf("kv snapshot write of %s returned no ETag", document.Bucket)
	}
	return *response.ETag, nil
}

document.text:
func (config BucketConfig) keyValueConfig(bucket string, replicas int) jetstream.KeyValueConfig {
	return jetstream.KeyValueConfig{Bucket: bucket, Description: config.Description, History: config.History,
		MaxValueSize: config.MaxValueSize, Compression: config.Compression, Storage: jetstream.FileStorage,
		Replicas: replicas}
}

func encodeDocument(document Document) ([]byte, error) {
	data, err := protocol.EncodeJSON(document)
	if err != nil {
		return nil, err
	}
	if len(data) > maxDocumentBytes {
		return nil, fmt.Errorf("kv snapshot of %s exceeds %d bytes", document.Bucket, maxDocumentBytes)
	}
	return data, nil
}

// decodeDocument accepts only a well-formed snapshot of exactly this cell's
// bucket: sorted unique valid keys whose values fit the recorded limit.
func decodeDocument(data []byte, cell, bucket string) (Document, error) {
	var document Document
	if err := protocol.DecodeStrict(data, &document, maxDocumentBytes); err != nil {
		return Document{}, fmt.Errorf("decode kv snapshot of %s: %w", bucket, err)
	}
	config := document.Config
	if document.Version != documentVersion || document.Cell != cell || document.Bucket != bucket ||
		document.StreamCreated.IsZero() || document.Sequence == 0 || document.TakenAt.IsZero() ||
		config.History < 1 || config.History > 64 || config.MaxValueSize == 0 || config.MaxValueSize < -1 {
		return Document{}, fmt.Errorf("kv snapshot of %s is not a valid snapshot of cell %s", bucket, cell)
	}
	for index, entry := range document.Entries {
		if !validKey(entry.Key) || index > 0 && document.Entries[index-1].Key >= entry.Key ||
			config.MaxValueSize > 0 && len(entry.Value) > int(config.MaxValueSize) {
			return Document{}, fmt.Errorf("kv snapshot of %s has an invalid, unsorted or oversized entry", bucket)
		}
	}
	return document, nil
}

func validKey(key string) bool {
	return kvKeyPattern.MatchString(key) && !strings.HasPrefix(key, ".") && !strings.HasSuffix(key, ".")
}

func validBuckets(buckets []string) error {
	for index, bucket := range buckets {
		if !kvBucketPattern.MatchString(bucket) || bucket == planBucket || slices.Contains(buckets[:index], bucket) {
			return fmt.Errorf("kv snapshot bucket %q is invalid or repeated", bucket)
		}
	}
	return nil

restore.text:
func openPlans(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.KeyValue, error) {
	plans, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: planBucket,
		Description: "Regional KV snapshot restore decision", History: 1, MaxValueSize: maxPlanBytes,
		Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return nil, fmt.Errorf("open kv restore plan: %w", err)
	}
	return plans, nil
}

func readPlan(ctx context.Context, plans jetstream.KeyValue) (restorePlan, uint64, bool, error) {
	entry, err := plans.Get(ctx, restorePlanKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return restorePlan{}, 0, false, nil
	}
	if err != nil {
		return restorePlan{}, 0, false, fmt.Errorf("read kv restore plan: %w", err)
	}
	var plan restorePlan
	if err := protocol.DecodeStrict(entry.Value(), &plan, maxPlanBytes); err != nil {
		return restorePlan{}, 0, false, fmt.Errorf("decode kv restore plan: %w", err)
	}
	if plan.Version != documentVersion || plan.State != stateRunning && plan.State != stateComplete ||
		plan.DecidedAt.IsZero() || validBuckets(plan.Buckets) != nil {
		return restorePlan{}, 0, false, errors.New("kv restore plan is invalid")
	}
	return plan, entry.Revision(), true, nil
}

// RestoreComplete reports whether this cell already completed its restore.
// It needs no Object Storage, so an ordinary controller restart stays
// independent of OCI.
func RestoreComplete(ctx context.Context, js jetstream.JetStream, replicas int) (bool, error) {
	plans, err := openPlans(ctx, js, replicas)
	if err != nil {
		return false, err
	}
	plan, _, found, err := readPlan(ctx, plans)
	return found && plan.State == stateComplete, err
}

// Restore runs the cell's restore plan, deciding it first when no
// controller has. It must finish before any owner opens a bucket. A value is
// written only if its key never had any revision in this cell, so a
// concurrent restorer or a live update or delete always wins.
func Restore(ctx context.Context, js jetstream.JetStream, objects *Objects, buckets []string, replicas int,
	now time.Time,
) (RestoreReport, error) {
	if err := validBuckets(buckets); err != nil {
		return RestoreReport{}, err
	}
	plans, err := openPlans(ctx, js, replicas)
	if err != nil {
		return RestoreReport{}, err
	}
	plan, revision, found, err := readPlan(ctx, plans)
	if err != nil || found && plan.State == stateComplete {
		return RestoreReport{}, err
	}
	documents := map[string]Document{}
	if !found {
		plan = restorePlan{Version: documentVersion, State: stateRunning, DecidedAt: now.UTC()}
		// A cell whose authority log already holds records kept its
		// JetStream state, so it is live and restores nothing; it reads no
		// OCI, and enabling snapshots on a live cell cannot stop its boot.
		fresh, err := neverWritten(ctx, js, authority.ControlStreamName)
		if err != nil {
			return RestoreReport{}, err
		}
		if !fresh {
			buckets = nil
		}
		for _, bucket := range buckets {
			empty, err := neverWritten(ctx, js, "KV_"+bucket)
			if err != nil {
				return RestoreReport{}, err
			}
			if !empty {
				continue
			}
			document, _, ok, err := objects.Get(ctx, bucket)
			if err != nil {
				return RestoreReport{}, err
			}
			if ok {
				plan.Buckets = append(plan.Buckets, bucket)
				documents[bucket] = document
			}
		}
		data, err := protocol.EncodeJSON(plan)
		if err != nil {
			return RestoreReport{}, err
		}
		revision, err = plans.Create(ctx, restorePlanKey, data)
		if errors.Is(err, jetstream.ErrKeyExists) {
			// Another controller decided first; follow its plan.
			plan, revision, found, err = readPlan(ctx, plans)
			if err == nil && !found {
				err = errors.New("kv restore plan vanished after a conflicting create")
			}
			if err != nil || plan.State == stateComplete {
				return RestoreReport{}, err
			}
			documents = map[string]Document{}
		} else if err != nil {
			return RestoreReport{}, fmt.Errorf("record kv restore plan: %w", err)
		}
	}
	report := RestoreReport{Buckets: plan.Buckets}
	for _, bucket := range plan.Buckets {
		document, ok := documents[bucket]
		if !ok {
			if document, _, ok, err = objects.Get(ctx, bucket); err != nil {
				return report, err
			}
			if !ok {
				return report, fmt.Errorf("planned kv snapshot of %s is missing", bucket)
			}
		}
		written, kept, err := restoreBucket(ctx, js, document, replicas)
		report.Written += written
		report.Kept += kept
		if err != nil {
			return report, err
		}
	}
	plan.State = stateComplete
	data, err := protocol.EncodeJSON(plan)
	if err != nil {
		return report, err
	}
	if _, err := plans.Update(ctx, restorePlanKey, data, revision); err != nil {
		// A plan only moves from running to complete, so a lost race is fine
		// once the plan reads complete.
		current, _, found, readErr := readPlan(ctx, plans)
		if readErr != nil || !found || current.State != stateComplete {
			return report, fmt.Errorf("complete kv restore plan: %w", errors.Join(err, readErr))
		}
	}
	return report, nil
}

// neverWritten asks the stream leader, through a fresh STREAM.INFO request
// (CachedInfo returns that reply), whether the stream ever stored a message.
func neverWritten(ctx context.Context, js jetstream.JetStream, name string) (bool, error) {
	stream, err := js.Stream(ctx, name)
	if errors.Is(err, jetstream.ErrStreamNotFound) {
		return true, nil
	}
	if err != nil {
		return false, fmt.Errorf("inspect %s: %w", name, err)
	}
	return stream.CachedInfo().State.LastSeq == 0, nil
}

func restoreBucket(ctx context.Context, js jetstream.JetStream, document Document, replicas int) (int, int, error) {
	kv, err := js.KeyValue(ctx, document.Bucket)
	if errors.Is(err, jetstream.ErrBucketNotFound) {
		kv, err = js.CreateKeyValue(ctx, document.Config.keyValueConfig(document.Bucket, replicas))
		if errors.Is(err, jetstream.ErrBucketExists) {
			kv, err = js.KeyValue(ctx, document.Bucket)
		}
	}
	if err != nil {
		return 0, 0, fmt.Errorf("open %s for restore: %w", document.Bucket, err)
	}
	written, kept := 0, 0
	for _, entry := range document.Entries {
		// Revision 0 requires a key with no revision at all, not even a
		// delete marker, so a deleted key is never brought back.
		_, err := kv.Update(ctx, entry.Key, entry.Value, 0)
		switch {
		case err == nil:
			written++
		case errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch):
			kept++
		default:
			return written, kept, fmt.Errorf("restore %s: %w", document.Bucket, err)
		}
	}
	return written, kept, nil
}

